import json,re
j=json.load(open('p05.json',encoding='utf-8'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,p+'.'+str(k))
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v,p+f'[{i}]')
    else:
        yield p,o
hits=[]
for p,v in walk(j):
    if isinstance(v,str) and re.search(r'talsam|talisman|necklace|strung|amulet|Muslim|silver',v,re.I) and len(v)<300:
        hits.append((p,v))
for p,v in hits:
    print(p,'=>',v.replace(chr(10),' ')[:250])
print('---P04---')
t=open('p04.txt',encoding='utf-8').read()
for w in ['Mughal','nephrite','jade','harm']:
    print(w, t.lower().find(w.lower()))
print('---P06 folklore---')
t5=open('p05.json',encoding='utf-8').read()
print('folklore amulet holders' in t5)
print('---P07 extra---')
t7=open('p07.txt',encoding='utf-8').read()
for w in ['plague','frontal','eyes','ship','apotropaic','amulet','face']:
    print('p07',w, t7.lower().find(w.lower()))
t7w=open('p07w.txt',encoding='utf-8').read()
for w in ['plague','frontal','eyes','ship','apotropaic','amulet','face']:
    print('p07w',w, t7w.lower().find(w.lower()))
